/bin/bash -c "python3 - <<'PY'
from math import log2, floor, fsum
from itertools import permutations

def tier(w):
 return floor(log2(log2(1/w)))

def expected_cost(p,q):
 costs=[]
 for order in permutations(range(len(p))):
  priorities=[-tier(w)+(order[i]+1)/(len(p)+1) for i,w in enumerate(q)]
  def cost(indices,depth):
   if not indices: return 0
   r=max(indices,key=lambda i:priorities[i])
   k=indices.index(r)
   return p[r]*depth+cost(indices[:k],depth+1)+cost(indices[k+1:],depth+1)
  costs.append(cost(list(range(len(p))),1))
 return fsum(costs)/len(costs)
p=[.25,.30,.45]
print('KL overhead check: p=',p,'accurate expected cost=',expected_cost(p,p))
for eps in [1e-3,1e-5,1e-7]:
 q=[p[0]+eps,p[1]-eps,p[2]]
 kl=fsum(px*log2(px/qx) for px,qx in zip(p,q))
 print('epsilon=',eps,'tiers=',[tier(v) for v in q],'cost increase=',expected_cost(p,q)-expected_cost(p,p),'KL=',kl)
n=256
eps=1e-8
w=(1-eps)/n
wp=(1+eps)/n
print('Update check: n=',n,'old/new tiers=',tier(w),tier(wp),'log2 ratio=',log2(wp/w),'expected rotations to promote endpoint to root=',fsum(1/k for k in range(1,n+1))-1)
for length in [2,4,8]:
 print('B-tree negative-tier construction: L=',length,'log2(B)=',4**length,'heavy tiers=',list(range(-length,0)),'depth of last heavy key=',length,'log_B(1/w_last)=',.25)
PY"
